<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\BrandLink; use App\Services\AuditService; use App\Support\BrandContext; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class BrandLinkController extends Controller { public function index(BrandContext $ctx){$this->authorize('update',$ctx->brand());return view('admin.links',['links'=>$ctx->brand()->allLinks()->get()]);} public function store(Request $r,BrandContext $ctx,AuditService $audit){$this->authorize('update',$ctx->brand());$data=$this->valid($r);$link=$ctx->brand()->allLinks()->create($data);$audit->record('brand_links.created',$link,[],$link->toArray());return back()->with('status','連結已新增。');} public function update(Request $r,BrandLink $link,BrandContext $ctx,AuditService $audit){abort_unless($link->brand_id===$ctx->id(),404);$this->authorize('update',$link);$before=$link->toArray();$link->update($this->valid($r));$audit->record('brand_links.updated',$link,$before,$link->fresh()->toArray());return back()->with('status','連結已更新。');} public function destroy(BrandLink $link,BrandContext $ctx,AuditService $audit){abort_unless($link->brand_id===$ctx->id(),404);$this->authorize('delete',$link);$audit->record('brand_links.deleted',$link,$link->toArray());$link->delete();return back()->with('status','連結已刪除。');} private function valid(Request $r):array{return $r->validate(['type'=>['required',Rule::in(['instagram','facebook','line','website','other'])],'label'=>'required|string|max:100','url'=>['required','url:http,https','max:2000'],'sort_order'=>'required|integer|min:0|max:9999','is_enabled'=>'nullable|boolean'])+['is_enabled'=>$r->boolean('is_enabled')];}}
